-- hybrid-gpu.lua: generated by first-launch.sh. Load it from hyprland.lua with:
--   require('hybrid-gpu')
-- The key names below are unverified on your Hyprland version. If
-- `hyprctl configerrors` complains, check /usr/share/hypr/stubs/hl.meta.lua.

-- The external port is wired to the NVIDIA GPU. With HDR and colour management
-- active, the NVIDIA driver sent an HDR infoframe while Hyprland rendered SDR,
-- atomic commits failed with "Invalid argument", and the picture went pink.
-- Turning HDR handling off removed the pink.
hl.config({ render = { cm_enabled = false } })

-- Keep workspace 1 on the laptop panel even when an external monitor
-- initialises first (it does when NVIDIA is the primary GPU).
hl.workspace_rule({ workspace = '1', monitor = 'eDP-1', default = true })

-- Per-monitor HDR off: add these two keys to your own hl.monitor() line for each
-- external output (mode, position and scale stay in your monitors config):
--   supports_hdr = 0, supports_wide_color = 0
-- connected now: DP-4
